// Dedupe the GitHub SCOUT_PL snapshot against everything the band
// already knows, then map the survivors onto SCOUT.OPPORTUNITIES' columns.
//
// Dedupe universe, per the scout's own rule (FLOW_MAP: URL + tytuł +
// organizator, and MASTER as the canonical CRM):
//   - every Dedupe Key a sheet already carries;
//   - every destination URL, normalized (scheme/www./trailing slash/query
//     folded — the same page spelled two ways is the same page);
//   - every opportunity title's lead words ('KozyNostra Rock Fest' matches
//     'KozyNostra Rock Fest — Przegląd Zespołów');
//   - every public email any file lists, for the contact side.
//
// A GH row that hits ANY of those is already known and skipped — a
// duplicate append is the failure mode the whole job exists to prevent,
// so a match in doubt counts as a hit. Contacts and organizers are NOT
// appended to the sheet (user call: Postgres-only via the CrowdRelay
// rescan this job triggers); they only enrich a new row's Public Contact.

const MAX_APPEND = 20; // SCOUT AUTO FLOW_MAP: 'Maks. 20/run'.

function clean(v) { return String(v === undefined || v === null ? '' : v).trim(); }
function lower(v) { return clean(v).toLowerCase(); }
function normUrl(v) {
  let u = lower(v);
  if (!u.startsWith('http')) return '';
  u = u.replace(/^https?:\/\//, '').replace(/^www\./, '');
  u = u.split('#')[0].split('?')[0].replace(/\/+$/, '');
  return u;
}
function leadSlug(v) {
  // The lead segment before the em-dash, first three words — the piece of
  // a title every sheet spells the same way.
  const lead = lower(v).split(/[—–]/)[0].replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
  return lead.split(' ').filter(Boolean).slice(0, 3).join('-');
}
function hostOf(v) {
  const u = normUrl(v);
  return u ? u.split('/')[0] : '';
}

const itemsOf = (name) => { try { return $(name).all().map(i => i.json); } catch (e) { return []; } };

// ---- known universe -----------------------------------------------------
const urls = new Set(), keys = new Set(), leads = new Set(), emails = new Set();
const learn = (row, fields) => {
  for (const f of fields.urls || []) { const u = normUrl(row[f]); if (u) urls.add(u); }
  for (const f of fields.keys || []) { const k = lower(row[f]); if (k) keys.add(k); }
  for (const f of fields.leads || []) { const s = leadSlug(row[f]); if (s) leads.add(s); }
  for (const f of fields.emails || []) { const e = lower(row[f]); if (e.includes('@')) emails.add(e); }
};

itemsOf('GS — SCOUT.OPPORTUNITIES').forEach(r => learn(r, { keys: ['Dedupe Key'], urls: ['URL'], leads: ['Name'], emails: ['Public Contact'] }));
itemsOf('GS — SCOUT.META_TARGETS').forEach(r => learn(r, { keys: ['Dedupe Key'], urls: ['Public URL / Username'], leads: ['Name'], emails: ['Public Contact'] }));
itemsOf('GS — SCOUT.SUPPORT_TARGETS').forEach(r => learn(r, { keys: ['Dedupe Key'], urls: ['Public URL'], leads: ['Band / Artist'] }));
itemsOf('GS — SCOUT.OUTREACH_LOG').forEach(r => learn(r, { leads: ['Recipient / Organization'], emails: ['Public Email'] }));
itemsOf('GS — MASTER.OPPORTUNITIES').forEach(r => learn(r, { urls: ['Application_URL'], leads: ['Opportunity_Name'] }));
itemsOf('GS — MASTER.ENTITIES').forEach(r => learn(r, { urls: ['Website'], leads: ['Canonical_Name', 'Display_Name'], emails: ['Primary_Email'] }));
itemsOf('GS — MASTER.CONTACTS').forEach(r => learn(r, { emails: ['Email'] }));
itemsOf('GS — AUTO.OPPORTUNITIES').forEach(r => learn(r, { keys: ['Dedupe_Key'], urls: ['URL'], leads: ['Title'], emails: ['Contact_Email'] }));
itemsOf('GS — AUTO.MARCIN_FEED').forEach(r => learn(r, { keys: ['Dedupe Key'], urls: ['URL'], leads: ['Name'], emails: ['Public Contact'] }));

// ---- the snapshot --------------------------------------------------------
const snapshot = itemsOf('Fetch SCOUT_PL snapshot')[0] || {};
const sheets = snapshot.sheets || {};
const rowsOf = (name) => {
  const sh = sheets[name];
  if (!sh || !Array.isArray(sh.headers) || !Array.isArray(sh.rows)) return [];
  return sh.rows.map(cells => Object.fromEntries(sh.headers.map((h, i) => [h, cells[i]])));
};
const oppRows = rowsOf('OPPORTUNITIES');
const contactRows = [...rowsOf('CONTACTS'), ...rowsOf('ORGANIZERS'), ...rowsOf('CANONICAL_APPEND')];

// Contact enrichment: organizer name or site host → a public email the
// snapshot itself lists.
const contactByName = new Map(), contactByHost = new Map();
for (const c of contactRows) {
  const email = lower(c.Email);
  if (!email.includes('@')) continue;
  for (const n of [c.Organization, c['Organization/Event'], c.Name]) {
    const key = lower(n);
    if (key && !contactByName.has(key)) contactByName.set(key, email);
  }
  for (const n of [c.Website, c.Source_URL, c.Source, c['History/Notes']]) {
    const host = hostOf(n);
    if (host && !contactByHost.has(host)) contactByHost.set(host, email);
  }
}

const skipped = { url: 0, lead: 0, key: 0 };
const candidates = [];
for (const r of oppRows) {
  const name = clean(r.Name);
  if (!name) continue;
  const url = normUrl(r.Source_URL);
  if (url && urls.has(url)) { skipped.url++; continue; }
  const lead = leadSlug(name);
  if (lead && leads.has(lead)) { skipped.lead++; continue; }
  candidates.push(r);
}
// Strong-fit findings first; input order keeps the rest stable.
const priorityRank = { A: 0, B: 1, C: 2, D: 3 };
const fitRank = (r) => {
  const priority = clean(r.Priority).toUpperCase();
  const score = Number(clean(r.Relevance_Score));
  return [
    priorityRank[priority] ?? 9,
    Number.isFinite(score) ? -score : 0,
    lower(r.Name)
  ];
};
candidates.sort((a, b) => {
  const aa = fitRank(a), bb = fitRank(b);
  return aa[0] - bb[0] || aa[1] - bb[1] || aa[2].localeCompare(bb[2]);
});
const toAppend = candidates.slice(0, MAX_APPEND).map(r => {
  const organizer = clean(r.Organizer);
  const email = clean(r.Contact_Email) || contactByName.get(lower(organizer)) || contactByHost.get(hostOf(r.Source_URL)) || '';
  const lead = leadSlug(r.Name) || 'find';
  const kind = /contest|konkurs|competition|przegl/i.test(clean(r.Type)) ? 'contest' : 'festival';
  const country = clean(r.Country) || clean(r.Voivodeship).split('/')[0].trim();
  const countryCity = [country, clean(r.City)].filter(Boolean).join(' / ');
  const economics = clean(r.Economics);
  const routing = [
    clean(r.Verification),
    clean(r.Routing_Source),
    clean(r.Distance_Km) ? ('distance_km=' + clean(r.Distance_Km)) : '',
    clean(r.Nights_Away) ? ('nights_away=' + clean(r.Nights_Away)) : ''
  ].filter(Boolean);
  return {
    'Name': clean(r.Name),
    'Type': clean(r.Type),
    'Country / City': countryCity,
    'Deadline': clean(r.Application_Deadline),
    'Event Date': clean(r.Event_Date),
    'URL': clean(r.Source_URL),
    'Public Contact': email,
    'Submission Method': clean(r.Submission_Method) || 'Official call / registration route — verify on site',
    'Free to Apply': clean(r.Free_To_Apply) || (/free|bez op/i.test(economics) ? 'Tak' : ''),
    'Relevance Score': clean(r.Relevance_Score),
    'Priority': clean(r.Priority) || (/strong/i.test(clean(r.Eligibility)) ? 'B' : 'C'),
    'Status': clean(r.Current_Status) || 'Do weryfikacji',
    'Why Fit': clean(r.Why_Fit) || clean(r.Eligibility),
    'Red Flags': clean(r.Red_Flags),
    'Next Step': clean(r.Next_Action),
    'Dedupe Key': clean(r.Dedupe_Key) || `${lead}|${kind}|virya`,
    'Raw Snippet': clean(r.Evidence).slice(0, 500),
    'Source Checked': clean(r.Source_Checked) || clean(snapshot.run_date),
    'Outreach Date': '',
    'Notes': [clean(r.VIRYA_History), clean(r.Next_Cycle), economics, ...routing].filter(Boolean).join(' | ')
  };
});

const commit = String($env.VIRYA_SCOUT_SYNC_COMMIT || '').toUpperCase() === 'TRUE';
return [{
  json: {
    commit,
    toAppend,
    appendedPreview: toAppend.map(r => r.Name).slice(0, 8),
    overflow: Math.max(0, candidates.length - toAppend.length),
    counts: {
      snapshot_rows: oppRows.length,
      new_candidates: candidates.length,
      appended: toAppend.length,
      skipped_by_url: skipped.url,
      skipped_by_lead: skipped.lead,
      known_universe: { urls: urls.size, keys: keys.size, leads: leads.size, emails: emails.size }
    }
  }
}];

// Aggregates regardless of the branch taken — dry runs report what
// would have appended, commits report what did.
const dedupe = $('Dedupe & map new rows').first().json;
let appended = 0;
try { appended = $('Append to SCOUT.OPPORTUNITIES').all().length; } catch (e) {}
const c = dedupe.counts;
const lines = [
  '**VIRYA — scout registry sync**',
  '',
  dedupe.commit ? 'Tryb: ZAPIS do SCOUT.OPPORTUNITIES' : 'Tryb: PROBNY (nic nie dopisano)',
  'Snapshot rows: ' + c.snapshot_rows + ' → new candidates: ' + c.new_candidates,
  (dedupe.commit ? 'Appended: ' : 'Would append: ') + (dedupe.commit ? appended : c.appended) + (c.overflow > 0 ? ' (+' + c.overflow + ' over the 20/run cap)' : ''),
  'Skipped — same URL: ' + c.skipped_by_url + ', same title: ' + c.skipped_by_lead,
  'Known universe: ' + c.known_universe.urls + ' urls / ' + c.known_universe.keys + ' dedupe keys / ' + c.known_universe.leads + ' titles / ' + c.known_universe.emails + ' emails',
  '',
  'Nowe: ' + dedupe.appendedPreview.join(', ')
];
if (!dedupe.commit) lines.push('', 'Ustaw VIRYA_SCOUT_SYNC_COMMIT=TRUE i uruchom ponownie, aby dopisac.');
const content = lines.join('\n').slice(0, 1900);
return [{ json: { discordBody: JSON.stringify({ content, allowed_mentions: { parse: [] } }) } }];

// Documentation node — never executes.
//
// Where this job's data goes:
//
//  - scout_runs/current.json is the current SCOUT run snapshot (SCOUT_PL or SCOUT_EUROPE), the same
//    rows database_festivals.xlsx renders. Reading the JSON avoids parsing
//    the binary and stays inside the repo's validation contract
//    (the crowdrelay-db validator guards its north-star schema).
//  - Appends land ONLY on SCOUT.OPPORTUNITIES — the human scout file the
//    team edits. GH contacts/organizers/canonical-append rows never write
//    a sheet; they enrich a new row's Public Contact and reach Postgres
//    through the CrowdRelay rescan this job triggers.
//  - SCOUT AUTO is a per-run snapshot and MASTER is the CRM truth — both
//    are read, never written by this workflow.
//
// What CrowdRelay does with the same files: the gdrive + github registry
// workers re-run the shared sheet intake — OPPORTUNITIES →
// team_opportunities, META_TARGETS → beacons, SUPPORT_TARGETS → peer_acts,
// every email column → drive_contacts — all deduped on each registry's
// own conflict key, so a re-run of an unchanged file is a no-op.
//
// Env: VIRYA_SCOUT_SHEET_ID, VIRYA_MASTER_SHEET_ID,
// VIRYA_SCOUT_AUTO_SHEET_ID, VIRYA_REGISTRY_REPO/REF (optional,
// defaults wojciechbator/crowdrelay-db@main), VIRYA_SCOUT_SYNC_COMMIT,
// CROWDRELAY_INTERNAL_BASE_URL (or CROWDRELAY_API_URL),
// CROWDRELAY_COMMERCE_TOKEN, VIRYA_OPS_ALERT_WEBHOOK_URL.
return [];
